{
  "schemaVersion": "0.2",
  "slug": "im-chat",
  "name": "IM chat",
  "status": "experimental",
  "purpose": "Conversation fragment with room list, chat bubbles, markdown replies, and a rich-text composer.",
  "scenarios": [
    "Read a seeded support thread with markdown from the assistant",
    "Compose and send a reply from the editor",
    "Show an empty state when the thread has no messages"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onSend": {
      "type": "event",
      "required": false,
      "description": "Called with plain text after the composer is submitted."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Thread has one or more messages." },
    { "name": "empty", "description": "No messages to show." }
  ],
  "composition": {
    "allowedParents": ["page", "app-shell"],
    "allowedChildren": ["chat-bubble", "markdown-renderer", "editor", "list", "button", "card", "empty-state", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not treat the editor HTML as a sanitizer-complete store; user text is stripped to plain copy.",
    "Do not claim 21 authored languages; 19 locales are ICU skeletons."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches rooms, bubbles, editor, toolbar, and send", "Activate send to append the reply"],
    "focus": "Composer and send stay in document order with a visible focus ring.",
    "labeling": "Rooms, thread, composer, and send have accessible names.",
    "wcag": ["2.1.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Rooms stack above the thread; @container at 48rem places rooms in a side column. No viewport media queries.",
    "breakpoints": {
      "compact": "Rooms stack above the thread.",
      "medium": "Rooms sit in a side column at 48rem container inline-size.",
      "large": "Rooms remain in a side column."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "im-chat",
    "states": ["default", "empty"],
    "intents": ["converse"]
  }
}

import { Button, Card, ChatBubble, Editor, EmptyState, List, MarkdownRenderer, Typography } from '@chameleon-ui/components'
import { useState } from 'react'
import { createBlockCopy } from '../copy.js'
import { imChatLocaleTrees } from './locale-map.js'
import './styles.css'

export interface ChatMessage {
  id: string
  role: 'user' | 'assistant' | 'system'
  markdown: string
  time?: string
}

export interface ImChatProps {
  locale?: string
  messages?: ChatMessage[]
  rooms?: string[]
  onSend?: (markdown: string) => void
  className?: string
}

function htmlToPlainText(html: string) {
  return html.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim()
}

function seedMessages(t: (key: string) => string): ChatMessage[] {
  return [
    { id: 'msg-1', role: 'user', markdown: t('im.seedUser'), time: '09:41' },
    { id: 'msg-2', role: 'assistant', markdown: t('im.seedAssistant'), time: '09:42' },
  ]
}

export function ImChat({ locale = 'en', messages: initialMessages, rooms, onSend, className }: ImChatProps) {
  const { t } = createBlockCopy(imChatLocaleTrees, locale)
  const [messages, setMessages] = useState<ChatMessage[]>(initialMessages ?? seedMessages(t))
  const [draft, setDraft] = useState('')
  const [composerKey, setComposerKey] = useState(0)
  const [error, setError] = useState<string | null>(null)
  const classes = ['cu-block-im-chat', className].filter(Boolean).join(' ')
  const roomItems = rooms ?? [t('im.roomSupport'), t('im.roomDesign'), t('im.roomOps')]

  const handleSend = () => {
    const text = htmlToPlainText(draft)
    if (!text) {
      setError(t('im.errorRequired'))
      return
    }
    const userMessage: ChatMessage = {
      id: `msg-${Date.now()}`,
      role: 'user',
      markdown: text,
    }
    const assistantMessage: ChatMessage = {
      id: `msg-${Date.now()}-reply`,
      role: 'assistant',
      markdown: t('im.assistantReply'),
    }
    setMessages((current) => [...current, userMessage, assistantMessage])
    setDraft('')
    setError(null)
    setComposerKey((value) => value + 1)
    onSend?.(text)
  }

  return (
    <section
      className={classes}
      data-ai-role="im-chat"
      data-ai-intent="converse"
      data-ai-state={messages.length === 0 ? 'empty' : 'default'}
    >
      <div className="cu-block-im-chat__header">
        <Typography variant="heading-1">{t('im.title')}</Typography>
        <Typography variant="body">{t('im.subtitle')}</Typography>
        <p className="cu-block-im-chat__meta">{t('im.messageCount', { count: messages.length })}</p>
      </div>
      <div className="cu-block-im-chat__layout">
        <aside aria-label={t('im.roomsLabel')} className="cu-block-im-chat__rooms">
          <Typography as="h2" variant="heading-2">
            {t('im.roomsLabel')}
          </Typography>
          <List items={roomItems} />
        </aside>
        <Card className="cu-block-im-chat__thread" padding="md" variant="outlined">
          <Typography as="h2" variant="heading-2">
            {t('im.threadLabel')}
          </Typography>
          {messages.length === 0 ? (
            <EmptyState description={t('im.emptyDescription')} title={t('im.emptyTitle')} />
          ) : (
            <div className="cu-block-im-chat__messages">
              {messages.map((message) => (
                <ChatBubble
                  key={message.id}
                  label={message.role === 'user' ? t('im.userLabel') : t('im.assistantLabel')}
                  role={message.role}
                  status={message.role === 'user' ? 'sent' : undefined}
                  statusLabel={message.role === 'user' ? t('im.sentLabel') : undefined}
                  time={message.time}
                >
                  {message.role === 'assistant' ? (
                    <MarkdownRenderer label={t('im.assistantLabel')} markdown={message.markdown} />
                  ) : (
                    message.markdown
                  )}
                </ChatBubble>
              ))}
            </div>
          )}
          {error ? (
            <p className="cu-block-im-chat__error" role="alert">
              {error}
            </p>
          ) : null}
          <div className="cu-block-im-chat__composer">
            <Editor
              key={composerKey}
              boldLabel={t('im.bold')}
              italicLabel={t('im.italic')}
              label={t('im.composerLabel')}
              onChange={setDraft}
              placeholder={t('im.placeholder')}
            />
            <Button onClick={handleSend} type="button">
              {t('im.send')}
            </Button>
          </div>
        </Card>
      </div>
    </section>
  )
}

.cu-block-im-chat {
  container-type: inline-size;
  container-name: chat;
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-im-chat__header,
.cu-block-im-chat__rooms,
.cu-block-im-chat__thread,
.cu-block-im-chat__messages,
.cu-block-im-chat__composer {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-block-im-chat__meta,
.cu-block-im-chat__error {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-im-chat__error {
  color: var(--cu-color-palette-brand);
}

.cu-block-im-chat__layout {
  display: grid;
  gap: var(--cu-space-3);
  grid-template-columns: minmax(0, 1fr);
}

.cu-block-im-chat__messages {
  min-block-size: calc(var(--cu-space-3) * 10);
}

@container chat (min-inline-size: 48rem) {
  .cu-block-im-chat__layout {
    grid-template-columns: minmax(8rem, 12rem) minmax(0, 1fr);
    align-items: start;
  }
}
